/**
 * Per-entity filter+sort allowlist generated by codegen-ts from @filterable/@sortable
 * metadata. Validates incoming HTTP filter params at the route boundary so the
 * Drizzle query layer never sees an unwhitelisted (field, op) combination.
 */

// FILTER_OPS, FilterOp, OPS_BY_SUBTYPE, and opsForSubType are canonical in
// @metaobjectsdev/metadata — import from there and re-export for backwards compat.
import {
  FILTER_OPS,
  OPS_BY_SUBTYPE,
  opsForSubType,
  FIELD_SUBTYPE_DATE,
  FIELD_SUBTYPE_TIME,
  FIELD_SUBTYPE_TIMESTAMP,
  FIELD_SUBTYPE_UUID,
  type FilterOp,
} from "@metaobjectsdev/metadata";
export { FILTER_OPS, OPS_BY_SUBTYPE, opsForSubType, type FilterOp };

export type FilterSubType = "string" | "number" | "boolean" | "datetime";

/**
 * The wire formats a filter value can be checked against, beyond the coarse
 * `FilterSubType`. Each is the `field.*` subtype whose Tier-1 wire encoding
 * (docs/features/api-contract.md, "Type encodings") the value must match — so the
 * values ARE the metamodel subtype names, not a second vocabulary.
 */
export const FILTER_VALUE_FORMATS = [
  FIELD_SUBTYPE_DATE,
  FIELD_SUBTYPE_TIME,
  FIELD_SUBTYPE_TIMESTAMP,
  FIELD_SUBTYPE_UUID,
] as const;
export type FilterValueFormat = (typeof FILTER_VALUE_FORMATS)[number];

export interface FilterFieldRule {
  readonly ops: readonly FilterOp[];
  readonly subType: FilterSubType;
  readonly leadingWildcard: boolean;
  /**
   * `subType: "datetime"` only. Set by codegen when the column was emitted under
   * `timestampMode: "date"`, i.e. the Drizzle column binds a JS `Date` rather than an
   * ISO string. The filter parser then coerces the query-string value with `new Date(...)`
   * instead of passing the raw string through — binding a string to a Date-typed column
   * throws `value.toISOString is not a function` at request time.
   *
   * Optional and defaulting to false, so an allowlist generated before this existed keeps
   * its exact previous behavior. `field.date` / `field.time` never set it: Drizzle types
   * both as strings under every dialect, so they are not governed by `timestampMode`.
   */
  readonly dateValues?: boolean;
  /**
   * The field's exact wire format, set by codegen for `field.date` / `field.time` /
   * `field.timestamp` / `field.uuid`. The filter parser rejects a value that does not
   * match it with `invalid_filter_value` instead of binding it — on SQLite a malformed
   * date compared as text and silently matched nothing; on Postgres it was a driver
   * error. Absent (an allowlist generated before this existed), a `datetime` value is
   * still checked against the union of the three temporal formats.
   */
  readonly format?: FilterValueFormat;
  /**
   * The declared members of a `field.enum` (`@values`), set by codegen. A value that is
   * not a member is rejected with `invalid_filter_value`. Absent, the parser falls back
   * to the Drizzle column's own `enumValues` when it has them.
   */
  readonly enumValues?: readonly string[];
}

export type FilterAllowlist = Readonly<Record<string, FilterFieldRule>>;

export interface SortFieldRule {
  readonly defaultOrder?: "asc" | "desc";
}

export type SortAllowlist = Readonly<Record<string, SortFieldRule>>;

/**
 * The direction a `?sort=<field>` runs: the caller's order if it gave one, else the
 * field's DECLARED `@sortableDefaultOrder`, else ascending.
 *
 * One function because there are two mounts that need it — the drizzle-fastify one and
 * the plain-fastify ObjectManager one — and when the declared-default read first landed
 * it landed in only the former, so the same query string against the same generated
 * allowlist returned rows in different orders depending on which mount a project
 * mounted. Delegating keeps that structurally impossible rather than merely tested.
 *
 * Returns the RAW string to interpret — it does not normalize or validate. That is
 * deliberate: a caller-supplied `?sort=x:bogus` must still 400, and a helper that
 * returned a tidy `"asc" | "desc"` would have to guess in order to be total, silently
 * accepting input both mounts reject today. Normalizing and reporting a bad order stays
 * with the caller, because the two mounts report it differently — one throws
 * `FilterParseError`, the other returns an error code — and that difference is part of
 * each one's contract. What is shared is only the precedence, which is the part that had
 * drifted.
 */
export function sortOrderSpec(
  allowlist: SortAllowlist,
  field: string,
  supplied: string | undefined,
): string {
  // The `?? "asc"` here is the ONLY place TypeScript's runtime spells the fallback. An
  // allowlist artifact carries declarations and nothing else — baking the default into
  // it would put the answer in two places per port, which is how a port drifts.
  return supplied ?? allowlist[field]?.defaultOrder ?? "asc";
}
